window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[43]={"id":"043","numero":43,"titre":"Hémorragie génitale chez la femme","objectifs":[{"id":"43-1","rang":"A","rubrique":"Diagnostic","titre":"Déterminer, par l’examen clinique, l’origine du saignement et le quantifier","contenu":"<p>L’<span class=\"kw-def\">hémorragie génitale</span> chez la femme correspond à des <strong>pertes sanguines d’origine génitale extériorisées par l’orifice vulvaire</strong>, <strong>différentes des règles normales</strong>. La démarche clinique vise à <strong>localiser le saignement</strong> (haute <span class=\"kw-bio\">vs</span> basse), <strong>le quantifier</strong> et rechercher des <strong><span class=\"kw-alerte\">signes de gravité</span></strong>.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Repères : menstruations normales <span class=\"kw-bio\">vs</span> hémorragie</h4>\n      <table >\n        <thead><tr><th>Entité</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Menstruations normales</strong></td>\n            <td>\n              <strong>Durée :</strong> <span class=\"kw-chiffre\">3–6 jours</span> ;<br>\n              <strong>Quantité :</strong> pertes sanguines <span class=\"kw-chiffre\">50–80 mL</span> ;<br>\n              <strong>Flux :</strong> plus important durant les <span class=\"kw-chiffre\">2–3 premiers jours</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Hémorragie haute</strong></td>\n            <td>Origine <span class=\"kw-clinique\">endo-utérine</span> (<strong>endocol</strong> compris).</td>\n          </tr>\n          <tr>\n            <td><strong>Hémorragie basse</strong></td>\n            <td>Origine <span class=\"kw-clinique\">vulvaire, vaginale, cervicale</span> (<strong>exocol</strong> = partie visible au spéculum).</td>\n          </tr>\n          <tr>\n            <td><strong>Ménorragies</strong></td>\n            <td>\n              1ʳᵉ cause de consultation entre <span class=\"kw-chiffre\">30–50 ans</span>. Menstruations trop abondantes en volume (<span class=\"kw-chiffre\">> 80 mL</span>) ou en durée (<span class=\"kw-chiffre\">> 6 jours</span>) :<br>\n              <strong>Hyperménorrhées :</strong> durée normale, abondance > <span class=\"kw-chiffre\">80 mL</span> ;<br>\n              <strong>Macroménorrhées :</strong> durée > <span class=\"kw-chiffre\">6 jours</span>, abondance normale ;<br>\n              <strong>Polyménorrhées :</strong> anomalie de durée + abondance.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Métrorragies</strong></td>\n            <td>Saignements d’origine utérine <strong>entre les périodes de menstruation</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong>Ménométrorragies</strong></td>\n            <td>Association de <strong>ménorragies + métrorragies</strong>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Démarche clinique</h4>\n      <table >\n        <thead><tr><th>Temps</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Interrogatoire</strong></td>\n            <td>\n              <strong>Quantification :</strong> nombre de garnitures, caillots, vêtements tachés ;<br>\n              <strong><span class=\"kw-def\">Score</span> de Higham</strong> pour les ménorragies (<span class=\"kw-chiffre\">> 100</span> = ménorragies, <span class=\"kw-chiffre\">> 150–200</span> = saignement très abondant nécessitant PEC).\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Examen sous spéculum</strong></td>\n            <td>\n              <span class=\"kw-clinique\">Visualisation d’un saignement actif</span> et de son origine (endo-utérin, col, vagin) ;<br>\n              Recherche de <span class=\"kw-clinique\">lésion</span> cervicale, polype accouché par le col, ectropion.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Toucher vaginal</strong></td>\n            <td>Évaluation du <strong>volume utérin</strong>, recherche d’une <strong><span class=\"kw-clinique\">tuméfaction</span> latéro-utérine</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong>Évaluation spoliation</strong></td>\n            <td><span class=\"kw-bio\">HemoCue®</span>, <span class=\"kw-bio\">NFS</span> (taux d’<span class=\"kw-bio\">hémoglobine</span>).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Signes de gravité</span> — repérer d’emblée.</strong><br>\n        <span class=\"kw-alerte\">Anémie mal tolérée</span> : <span class=\"kw-clinique\">tachycardie</span>, <span class=\"kw-clinique\">pâleur</span>, <span class=\"kw-clinique\">dyspnée</span>, <span class=\"kw-clinique\">asthénie</span>, <span class=\"kw-clinique\">vertiges</span> ;<br>\n        <span class=\"kw-alerte\">Choc</span> : <span class=\"kw-clinique\">hypotension</span>, <span class=\"kw-clinique\">malaise</span>, <span class=\"kw-clinique\">sueurs</span>, extrémités froides, marbrures.<br>\n        <strong>CAT immédiate :</strong> <span class=\"kw-alerte\">hospitalisation</span>, <span class=\"kw-ttt\">2 VVP de bon calibre</span>, réchauffement, <span class=\"kw-ttt\">oxygénothérapie</span>, <span class=\"kw-bio\">NFS · hémostase · groupe-Rh (2 déterminations)</span>, <span class=\"kw-bio\">β-hCG</span> (sauf <span class=\"kw-ci\">grossesse</span> intra-utérine connue).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 35 — Anomalies cycle menstruel - métrorragie · 25 — <span class=\"kw-ci\">Grossesse</span> extra-utérine · 24 — Principales complications de la grossesse</em></p>","frequence":0,"liens":[{"href":"https://www.chu-lyon.fr/sites/default/files/score-higham.pdf","label":"Score de Higham (PDF, CHU Lyon)"}]},{"id":"43-2","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales causes d’hémorragie génitale","contenu":"<div class=\"callout callout-danger\">\n        <strong>Règle absolue.</strong> La <span class=\"kw-alerte\">grossesse</span> est la <strong>1ʳᵉ cause à éliminer</strong> chez toute femme en âge de procréer (<span class=\"kw-bio\">β-hCG plasmatique ou urinaire</span>).\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-def\">Classification</span> FIGO — <span class=\"kw-def\">PALM-COEIN</span></h4>\n      <table >\n        <thead>\n          <tr><th>Groupe</th><th>Étiologies</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>PALM</strong><br><em>(causes structurelles)</em></td>\n            <td>\n              <strong>P</strong> · Polype ;<br>\n              <strong>A</strong> · Adénomyose ;<br>\n              <strong>L</strong> · <span class=\"kw-etio\">Léiomyome</span> (sous-muqueux et autre) ;<br>\n              <strong>M</strong> · Malignité et hyperplasie.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>COEIN</strong><br><em>(causes non structurelles)</em></td>\n            <td>\n              <strong>C</strong> · Coagulopathie ;<br>\n              <strong>O</strong> · Ovulatoire (dysfonction) ;<br>\n              <strong>E</strong> · Endométriale ;<br>\n              <strong>I</strong> · Iatrogénie ;<br>\n              <strong>N</strong> · Non autrement précisée.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Étiologies selon le <span class=\"kw-def\">terrain</span></h4>\n      <table >\n        <thead><tr><th>Terrain</th><th>Causes à évoquer</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Adolescente</strong></td>\n            <td>\n              <span class=\"kw-bio\">Anomalie de l’hémostase</span> (Willebrand+++) ;<br>\n              <strong>Causes fonctionnelles :</strong> insuffisance lutéale, hyperœstrogénie relative par anovulation des 1ᵉʳˢ cycles.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Femme en âge de procréer</strong></td>\n            <td>\n              <strong>Toujours β-hCG d’abord</strong> ;<br>\n              <span class=\"kw-clinique\">Adénomyose / endométriose interne</span> ;<br>\n              <strong>Tumeurs bénignes du corps utérin :</strong> hyperplasie endométriale, polypes endométriaux, myomes/fibromes (surtout sous-muqueux).\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Femme ménopausée</strong></td>\n            <td>\n              <span class=\"kw-alerte\">Toute métrorragie = cancer jusqu’à preuve du contraire</span> :<br>\n              <strong>1.</strong> <span class=\"kw-etio\">Cancer endomètre</span> · <span class=\"kw-etio\">Cancer col</span> · <span class=\"kw-etio\">Cancer ovaire sécrétant</span> ;<br>\n              <strong>2.</strong> <span class=\"kw-etio\">Atrophie endométriale</span> (diagnostic d’exclusion).\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Causes liées à la <span class=\"kw-ci\">grossesse</span></h4>\n      <table >\n        <thead><tr><th>Période</th><th>Causes</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>1ᵉʳ trimestre</strong></td>\n            <td><span class=\"kw-ci\">Grossesse</span> intra-utérine évolutive · <span class=\"kw-alerte\">Grossesse extra-utérine</span> · Grossesse de localisation indéterminée · <strong><span class=\"kw-etio\">Fausse couche spontanée</span></strong> · <span class=\"kw-etio\">Grossesse arrêtée</span> · <span class=\"kw-etio\">Môle hydatiforme</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>2ᵉ trimestre</strong></td>\n            <td><span class=\"kw-etio\">Hématome placentaire</span> · <strong><span class=\"kw-etio\">Décollement marginal</span></strong> · <span class=\"kw-etio\">Placenta bas inséré</span> · Causes indéterminées.</td>\n          </tr>\n          <tr>\n            <td><strong>3ᵉ trimestre</strong></td>\n            <td><span class=\"kw-alerte\">Hématome rétroplacentaire</span> · <strong><span class=\"kw-etio\">Hématome décidual marginal</span></strong> · <span class=\"kw-alerte\">Placenta prævia</span> · <strong><span class=\"kw-etio\">Hémorragie de Benkiser</span></strong> · <span class=\"kw-alerte\">Rupture utérine</span> · Cause cervicale · Hémorragies de la délivrance (post-partum immédiat).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 25 — <span class=\"kw-ci\">Grossesse</span> extra-utérine · 24 — Principales complications de la grossesse · 300 — Tumeurs du col utérin et du corps utérin · 35 — Anomalies cycle menstruel - métrorragie</em></p>","frequence":0},{"id":"43-3","rang":"A","rubrique":"Étiologies","titre":"Différencier les causes organiques et les causes fonctionnelles","contenu":"<p>La dichotomie <strong>organique / fonctionnel</strong> est centrale : elle conditionne la stratégie diagnostique (imagerie, <span class=\"kw-bio\">biopsie</span>) et thérapeutique (<span class=\"kw-ttt\">chirurgie</span> <span class=\"kw-bio\">vs</span> hormonothérapie).</p>\n\n      <figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewBox=\"0 0 560 184\" role=\"img\" aria-label=\"Logigramme organique versus fonctionnel : si le bilan organique (imagerie pelvienne et biopsie d'endomètre) est normal, on retient une cause fonctionnelle, qui est un diagnostic d'élimination ; s'il est anormal, on retient une cause organique à traiter.\" style=\"height:auto;display:block;border-radius:8px\">\n          <text class=\"tx-title\" x=\"280\" y=\"13\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"600\">Hémorragies génitales — organique <span class=\"kw-bio\">vs</span> fonctionnel</text>\n          <rect class=\"fb-blue\" x=\"150\" y=\"26\" width=\"260\" height=\"46\" rx=\"6\"/>\n          <text class=\"tx-blue\" x=\"280\" y=\"46\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"600\">Bilan organique normal ?</text>\n          <text class=\"tx-blue\" x=\"280\" y=\"61\" text-anchor=\"middle\" font-size=\"8\">imagerie pelvienne + <span class=\"kw-ttt\">biopsie</span> d'endomètre</text>\n          <line class=\"ln\" x1=\"280\" y1=\"72\" x2=\"280\" y2=\"84\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"140\" y1=\"84\" x2=\"420\" y2=\"84\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"140\" y1=\"84\" x2=\"140\" y2=\"99\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"140,106 135,98 145,98\"/>\n          <line class=\"ln\" x1=\"420\" y1=\"84\" x2=\"420\" y2=\"99\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"420,106 415,98 425,98\"/>\n          <text class=\"tx-red\" x=\"96\" y=\"96\" text-anchor=\"middle\" font-size=\"8\" font-weight=\"700\">✗ anormal</text>\n          <text class=\"tx-ok\" x=\"464\" y=\"96\" text-anchor=\"middle\" font-size=\"8\" font-weight=\"700\">✓ normal</text>\n          <rect class=\"fb-red\" x=\"30\" y=\"108\" width=\"220\" height=\"66\" rx=\"6\"/>\n          <text class=\"tx-red\" x=\"140\" y=\"132\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\">Cause ORGANIQUE</text>\n          <text class=\"tx-red\" x=\"140\" y=\"148\" text-anchor=\"middle\" font-size=\"8\">substratum structurel</text>\n          <text class=\"tx-red\" x=\"140\" y=\"163\" text-anchor=\"middle\" font-size=\"8.5\">→ traiter la cause</text>\n          <rect class=\"fb-ok\" x=\"310\" y=\"108\" width=\"220\" height=\"66\" rx=\"6\"/>\n          <text class=\"tx-ok\" x=\"420\" y=\"132\" text-anchor=\"middle\" font-size=\"10.5\" font-weight=\"700\">Cause FONCTIONNELLE</text>\n          <text class=\"tx-ok\" x=\"420\" y=\"148\" text-anchor=\"middle\" font-size=\"8\">diagnostic d'élimination</text>\n          <text class=\"tx-ok\" x=\"420\" y=\"163\" text-anchor=\"middle\" font-size=\"8.5\">→ hormonothérapie</text>\n        </svg>\n        <figcaption>Le fonctionnel ne s'affirme qu'<strong>après</strong> un bilan organique normal (imagerie + biopsie d'endomètre selon le <span class=\"kw-def\">terrain</span>) — c'est un diagnostic d'élimination.</figcaption>\n      </figure>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Causes organiques (étiologies <span class=\"kw-def\">structurelles</span>)</h4>\n      <table >\n        <thead><tr><th>Site</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Vulve</strong></td>\n            <td>Traumatisme (interrogatoire, lésions visibles) ; tumeur vulvaire.</td>\n          </tr>\n          <tr>\n            <td><strong>Vagin</strong></td>\n            <td>Traumatisme · corps étranger · vaginite · tumeur vaginale.</td>\n          </tr>\n          <tr>\n            <td><strong>Col</strong></td>\n            <td>Traumatisme · <strong>Ectropion</strong> (saignements post-coïtaux, bénin) · <span class=\"kw-alerte\">Cancer du col</span> · <strong>Cervicite</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong>Endomètre</strong></td>\n            <td>\n              <strong>Endométrite</strong> (métrorragies + <span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">infectieux</span></span>, après accouchement / geste endo-utérin) ;<br>\n              <strong>Polype endométrial</strong> (visible au spéculum si accouché par le col) ;<br>\n              <strong>Hyperplasies endométriales</strong> (simples ou atypiques) ;<br>\n              <span class=\"kw-alerte\">Cancer de l’endomètre</span> (++ en péri-ménopause).\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Myomètre</strong></td>\n            <td>\n              <strong>Myome sous-muqueux</strong> (métrorragies + <span class=\"kw-clinique\">masse</span> pelvienne) ;<br>\n              <strong>Adénomyose</strong> (endomètre dans le myomètre, métrorragies + douleurs) ;<br>\n              <span class=\"kw-alerte\">Sarcome utérin</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Annexe / ovaire</strong></td>\n            <td>Salpingite · kyste / <strong>tumeur ovarienne sécrétante</strong> de stéroïdes.</td>\n          </tr>\n          <tr>\n            <td><strong>Coagulopathie</strong></td>\n            <td>Maladie de <strong>Willebrand</strong> (cause structurelle au sens FIGO « C »).</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Iatrogène</span></strong></td>\n            <td>Contraception (carence œstrogénique) · <span class=\"kw-etio\">anticoagulant</span> · DIU.</td>\n          </tr>\n          <tr>\n            <td><strong>Systémique</strong></td>\n            <td><span class=\"kw-etio\">Hypothyroïdie</span> · <span class=\"kw-etio\">lupus</span> · <span class=\"kw-etio\">insuffisance rénale chronique</span> · <span class=\"kw-ci\">insuffisance hépatique</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Causes fonctionnelles (<span class=\"kw-def\">diagnostic d’élimination</span>)</h4>\n      <table >\n        <thead><tr><th>Item</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Mécanisme</strong></td>\n            <td><span class=\"kw-bio\">Déséquilibre hormonal œstrogène / progestérone</span> induisant une altération de l’endomètre. Par définition, <strong>pas de substratum histopathologique utérin</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Terrain</span></strong></td>\n            <td>Fréquentes en <strong>péri-puberté</strong> et en <strong>péri-ménopause</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong>Trois tableaux types</strong></td>\n            <td>\n              <strong>Métrorragies prémenstruelles</strong> par <span class=\"kw-bio\">insuffisance lutéale</span> ;<br>\n              <strong>Métrorragies intermenstruelles</strong> du <strong>14ᵉ jour</strong> (ovulation) ;<br>\n              <strong>Métrorragies post-menstruelles</strong> par <span class=\"kw-bio\">insuffisance œstrogénique en début de cycle</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Iatrogènes possibles</strong></td>\n            <td>\n              <span class=\"kw-ttt\">COP</span> (arrêt / oubli ; faiblement dosés → relais plus œstrogénique) ;<br>\n              <span class=\"kw-ttt\">Progestatifs</span> (PO, SC, DIU) → spotting par atrophie endométriale ;<br>\n              <span class=\"kw-ttt\">Œstrogénothérapie</span> mal contrebalancée (hypertrophie endométriale, ex THM ménopause) ;<br>\n              DIU (malposition, infection) ; <span class=\"kw-etio\">anticoagulants</span>.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Piège EDN.</strong> Le diagnostic de cause fonctionnelle ne s’affirme qu’<strong>après élimination des causes organiques</strong> — imagerie pelvienne normale et, selon le <span class=\"kw-def\">terrain</span>, <span class=\"kw-bio\">biopsie</span> d’endomètre normale.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 35 — Anomalies cycle menstruel - métrorragie · 36 — Contraception</em></p>","frequence":0},{"id":"43-4","rang":"A","rubrique":"Examens complémentaires","titre":"Savoir prescrire les premiers examens biologiques à réaliser","contenu":"<p>Le bilan <span class=\"kw-ttt\">biologique</span> de <span class=\"kw-chiffre\">première intention</span> vise à <strong>chiffrer la spoliation</strong>, <strong>éliminer une <span class=\"kw-ci\">grossesse</span></strong> et <strong>dépister une coagulopathie</strong>.</p>\n\n      <table >\n        <thead><tr><th>Examen</th><th>Objectif</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-bio\">NFS</span></td>\n            <td>Quantification du retentissement (<strong>Hb</strong>) et <span class=\"kw-bio\">plaquettes</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\">β-hCG plasmatique ou urinaire</span></td>\n            <td><strong>Systématique</strong> chez toute femme en âge de procréer.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\">Bilan martial</span></td>\n            <td><strong>Ferritinémie + <span class=\"kw-bio\">CRP</span></strong> (un <span class=\"kw-def\">syndrome inflammatoire</span> peut masquer une hypoferritinémie).</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\">Bilan d’hémostase</span></td>\n            <td>\n              <strong><span class=\"kw-bio\">TP</span> · <span class=\"kw-bio\">TCA</span></strong> ;<br>\n              <strong>Dosage du facteur de Willebrand</strong> — <span class=\"kw-clinique\">indication large chez l’adolescente</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Groupe sanguin · Rh (2 déterminations)</strong></td>\n            <td>Si <span class=\"kw-alerte\">signes de gravité</span> ou hémorragie abondante (transfusion potentielle).</td>\n          </tr>\n          <tr>\n            <td><strong>Prélèvements bactériologiques cervico-vaginaux</strong></td>\n            <td>Si <span class=\"kw-clinique\">risque infectieux</span> ; si positifs → <strong><span class=\"kw-bio\">sérologies</span> <span class=\"kw-etio\">VIH</span> · VHB · VHC · syphilis</strong>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Devant une <span class=\"kw-alerte\">hémorragie sévère</span> : <span class=\"kw-bio\">NFS · hémostase · groupe-Rh (2 dét.) · β-hCG</span> en <span class=\"kw-chiffre\">première intention</span>, en parallèle de la mise en condition (2 VVP, <span class=\"kw-ttt\">oxygénothérapie</span>, réchauffement).\n      </div>","frequence":0},{"id":"43-5","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître l’indication de l’imagerie devant une hémorragie génitale chez la femme","contenu":"<p>L’imagerie pelvienne est <strong>systématique</strong> devant une hémorragie génitale, après élimination d’une <span class=\"kw-ci\">grossesse</span> pathologique. Hiérarchie en deux temps :</p>\n\n      <figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewBox=\"0 0 560 230\" role=\"img\" aria-label=\"Hiérarchie de l'imagerie devant une hémorragie génitale : échographie pelvienne en première intention ; en deuxième intention, soit hystérosonographie ou hystéroscopie diagnostique si l'échographie est normale avec échec du traitement ou lésion endométriale, soit IRM pelvienne en cas de suspicion de cancer, de cartographie de myomes ou d'adénomyose.\" style=\"height:auto;display:block;border-radius:8px\">\n          <text class=\"tx-title\" x=\"280\" y=\"14\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"600\">Hiérarchie de l'imagerie — hémorragie génitale</text>\n          <rect class=\"fb-blue\" x=\"160\" y=\"28\" width=\"240\" height=\"44\" rx=\"6\"/>\n          <text class=\"tx-blue\" x=\"280\" y=\"48\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"600\"><span class=\"kw-imagerie\">Échographie</span> pelvienne</text>\n          <text class=\"tx-blue\" x=\"280\" y=\"63\" text-anchor=\"middle\" font-size=\"8.5\">1ʳᵉ intention (sus-pubienne + endovaginale)</text>\n          <line class=\"ln\" x1=\"280\" y1=\"72\" x2=\"280\" y2=\"84\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"280,90 275,82 285,82\"/>\n          <rect class=\"fb-amber\" x=\"205\" y=\"92\" width=\"150\" height=\"30\" rx=\"6\"/>\n          <text class=\"tx-amber\" x=\"280\" y=\"111\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"600\">Imagerie 2ᵉ intention</text>\n          <line class=\"ln\" x1=\"280\" y1=\"122\" x2=\"280\" y2=\"134\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"140\" y1=\"134\" x2=\"420\" y2=\"134\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"140\" y1=\"134\" x2=\"140\" y2=\"149\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"140,156 135,148 145,148\"/>\n          <line class=\"ln\" x1=\"420\" y1=\"134\" x2=\"420\" y2=\"149\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"420,156 415,148 425,148\"/>\n          <rect class=\"fb-blue\" x=\"20\" y=\"158\" width=\"240\" height=\"62\" rx=\"6\"/>\n          <text class=\"tx-muted\" x=\"140\" y=\"174\" text-anchor=\"middle\" font-size=\"7\">si écho normale + échec ttt / <span class=\"kw-clinique\">lésion</span> endom.</text>\n          <text class=\"tx-blue\" x=\"140\" y=\"190\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"600\">Hystérosono / Hystéroscopie</text>\n          <text class=\"tx-blue\" x=\"140\" y=\"205\" text-anchor=\"middle\" font-size=\"7.5\">analyse de la cavité utérine</text>\n          <rect class=\"fb-blue\" x=\"300\" y=\"158\" width=\"240\" height=\"62\" rx=\"6\"/>\n          <text class=\"tx-muted\" x=\"420\" y=\"174\" text-anchor=\"middle\" font-size=\"7\">si cancer / cartographie myomes / adénomyose</text>\n          <text class=\"tx-blue\" x=\"420\" y=\"190\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"600\"><span class=\"kw-imagerie\">IRM</span> pelvienne</text>\n          <text class=\"tx-blue\" x=\"420\" y=\"205\" text-anchor=\"middle\" font-size=\"7.5\">(avec injection)</text>\n        </svg>\n        <figcaption>Échographie en 1ʳᵉ intention ; en 2ᵉ intention, hystérosono/hystéroscopie (cavité utérine) <em>ou</em> <span class=\"kw-imagerie\">IRM</span> (cancer, cartographie) — les deux sont au même rang, pas en série obligatoire.</figcaption>\n      </figure>\n\n      <table >\n        <thead><tr><th>Rang</th><th>Examen</th><th>Indications</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>1ʳᵉ intention</strong></td>\n            <td><span class=\"kw-imagerie\">Échographie pelvienne</span><br>(voies <strong>sus-pubienne</strong> + <strong>endovaginale</strong>)</td>\n            <td>\n              Examen de référence : tolérance, accessibilité, exploration utérus + endomètre + annexes ;<br>\n              Recherche d’un polype, myome, adénomyose, <span class=\"kw-clinique\">masse</span> annexielle, épaisseur endométriale.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>2ᵉ intention</strong></td>\n            <td><span class=\"kw-imagerie\">IRM pelvienne</span><br>(avec injection)</td>\n            <td>\n              Cartographie précise des myomes (avant <span class=\"kw-ttt\">chirurgie</span> / embolisation) ;<br>\n              Bilan d’adénomyose, suspicion de cancer utérin, malformation utérine complexe.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>2ᵉ intention</strong></td>\n            <td><span class=\"kw-imagerie\">Hystérosonographie</span><br>ou <span class=\"kw-imagerie\">Hystéroscopie diagnostique</span></td>\n            <td>\n              <strong>Meilleure analyse de la cavité utérine</strong>. Indiquées si :<br>\n              <strong>· Échec de traitement <span class=\"kw-etio\">médicamenteux</span></strong> avec <span class=\"kw-imagerie\">échographie</span> normale ;<br>\n              <strong>· <span class=\"kw-clinique\">Lésion</span> endométriale</strong> à l’écho (polype, hyperplasie atypique, myome sous-muqueux).\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Cas particulier — analyse du col.</strong> Devant un <span class=\"kw-clinique\">saignement post-coïtal</span> ou une <span class=\"kw-clinique\">hémorragie génitale basse</span> objectivée au spéculum :<br>\n        <strong>FCU / Test <span class=\"kw-etio\">HPV</span> :</strong> possibles mais résultat faussé par le sang (non indiqués si <span class=\"kw-clinique\">lésion</span> cervicale visible) ;<br>\n        <strong>Colposcopie + <span class=\"kw-bio\">biopsies</span> cervicales dirigées :</strong> diagnostic anatomopathologique.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 300 — Tumeurs du col utérin et du corps utérin · 25 — <span class=\"kw-ci\">Grossesse</span> extra-utérine</em></p>","frequence":1},{"id":"43-6","rang":"B","rubrique":"Examens complémentaires","titre":"Préciser l’intérêt et la place de prélèvements cyto- ou histologiques","contenu":"<p>Les prélèvements cyto-histologiques permettent d’<strong>éliminer une malignité</strong> et d’adapter la stratégie thérapeutique. Deux territoires distincts : <strong>endomètre</strong> et <strong>col</strong>.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-bio\">Biopsie</span> d’endomètre</h4>\n      <table >\n        <thead><tr><th>Item</th><th>Détails</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Indications</strong></td>\n            <td>\n              <span class=\"kw-clinique\">Patiente > 45 ans</span> ou <strong>ménopausée</strong> ;<br>\n              <strong><span class=\"kw-def\">Facteurs de risque</span> de cancer de l’endomètre</strong> (<span class=\"kw-etio\">obésité</span>, nulliparité, hyperœstrogénie chronique, THM, tamoxifène, <span class=\"kw-clinique\">syndrome de Lynch</span>).\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Modalités</strong></td>\n            <td>\n              <strong><span class=\"kw-bio\">Biopsie</span> à l’aveugle à la pipelle de Cornier</strong> (consultation, après hystéroscopie diagnostique éventuelle) ;<br>\n              <strong><span class=\"kw-bio\">Biopsies</span> dirigées à la pince lors d’une hystéroscopie diagnostique</strong> (sous AL ou bloc).\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Analyse du col utérin</h4>\n      <table >\n        <thead><tr><th>Examen</th><th>Place</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>FCU ou Test <span class=\"kw-etio\">HPV</span></strong></td>\n            <td>Possibles mais <span class=\"kw-clinique\">résultat faussé par la présence de sang</span> ; <strong>non indiqués</strong> si <span class=\"kw-clinique\">lésion</span> cervicale visible (on <span class=\"kw-bio\">biopsie</span> directement).</td>\n          </tr>\n          <tr>\n            <td><strong>Colposcopie + <span class=\"kw-bio\">biopsies</span> dirigées</strong></td>\n            <td>Indiquée devant un <span class=\"kw-clinique\">saignement post-coïtal</span>, une <strong><span class=\"kw-clinique\">lésion</span> cervicale visible</strong> ou une <strong>hémorragie génitale basse</strong>. Diagnostic anatomopathologique.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Prélèvements microbiologiques</h4>\n      <table >\n        <thead><tr><th>Indication</th><th>Examens</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Risque <span class=\"kw-etio\">infectieux</span></strong></td>\n            <td>\n              <span class=\"kw-bio\">Prélèvements bactériologiques cervico-vaginaux</span> (IST : Chlamydia, gonocoque, mycoplasmes) ;<br>\n              Si positivité → <strong><span class=\"kw-bio\">sérologies</span> <span class=\"kw-etio\">VIH</span>, VHB, VHC, syphilis</strong>.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 300 — Tumeurs du col utérin et du corps utérin</em></p>","frequence":0},{"id":"43-7","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principaux traitements médicaux et chirurgicaux des myomes","contenu":"<p>Le traitement des <span class=\"kw-def\">myomes utérins (fibromes)</span> dépend de la symptomatologie, du volume, du nombre, de la localisation et du <strong>désir de <span class=\"kw-ci\">grossesse</span></strong>. Trois axes thérapeutiques.</p>\n\n      <table >\n        <thead><tr><th>Axe</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Traitement médical</strong><br><em>(mise sous aménorrhée)</em></td>\n            <td>\n              <span class=\"kw-ttt\">Progestatifs PO</span> ou <span class=\"kw-ttt\">DIU au lévonorgestrel</span> ;<br>\n              <span class=\"kw-ttt\">Acide tranexamique</span> (antifibrinolytique) sur les épisodes hémorragiques ;<br>\n              <span class=\"kw-ttt\">Analogues de la GnRH</span> en préparation chirurgicale (mise sous aménorrhée + <span class=\"kw-ttt\">réduction</span> du volume myomateux).\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Traitement chirurgical</strong></td>\n            <td>\n              <strong><span class=\"kw-ttt\">Myomectomie</span></strong> (conservatrice — voie hystéroscopique pour myome sous-muqueux, voie cœlioscopique ou laparotomique pour les autres) ;<br>\n              <strong><span class=\"kw-ttt\">Hystérectomie</span></strong> en l’absence de désir de <span class=\"kw-ci\">grossesse</span> et en cas d’échec / multirécidive.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Radiologie interventionnelle</strong></td>\n            <td>\n              <span class=\"kw-imagerie\">Embolisation des artères utérines</span> :<br>\n              <strong>·</strong> Alternative à la <span class=\"kw-ttt\">chirurgie</span> ;<br>\n              <strong>·</strong> Discutée selon le désir de <span class=\"kw-ci\">grossesse</span> (impact possible sur la fertilité).\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Stratégie.</strong> Le choix se fait en fonction du <strong>désir de <span class=\"kw-ci\">grossesse</span></strong>, de la localisation (sous-muqueux = hystéroscopie ; intra-muraux/sous-séreux = cœlio/laparo) et de la <strong>tolérance <span class=\"kw-etio\">hémorragique</span></strong>.\n      </div>","frequence":0},{"id":"43-8","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principaux traitements de l’adénomyose","contenu":"<p>L’<span class=\"kw-def\">adénomyose</span> (présence d’endomètre ectopique dans le myomètre) responsable de <span class=\"kw-clinique\">méno-métrorragies</span> et de <span class=\"kw-clinique\">douleurs pelviennes</span> — stratégie en <strong>deux temps</strong>.</p>\n\n      <table >\n        <thead><tr><th>Rang</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>1ʳᵉ intention<br>(médical)</strong></td>\n            <td>\n              <span class=\"kw-ttt\">DIU au lévonorgestrel</span> — <strong>action atrophiante endométriale</strong>, traitement de référence.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>2ᵉ intention<br>(chirurgical, si échec)</strong></td>\n            <td>\n              <strong><span class=\"kw-ttt\">Endométrectomie</span></strong> — geste <span class=\"kw-clinique\">conservateur</span> (<span class=\"kw-ttt\">réduction</span> endométriale) ;<br>\n              <strong><span class=\"kw-ttt\">Hystérectomie</span></strong> — en cas d’<span class=\"kw-clinique\">échec ou refus du traitement chirurgical conservateur</span>, <strong>en l’absence de désir de <span class=\"kw-ci\">grossesse</span></strong>.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> <span class=\"kw-ttt\">DIU lévonorgestrel</span> = traitement de 1ʳᵉ intention de l’adénomyose. La <span class=\"kw-ttt\">chirurgie</span> n’intervient qu’<strong>après échec du traitement médical</strong>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 35 — Anomalies cycle menstruel - métrorragie · 36 — Contraception</em></p>","frequence":1},{"id":"43-9","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge d’une hémorragie génitale","contenu":"<p>La PEC dépend de <strong>l’étiologie</strong> et du <strong>désir de <span class=\"kw-ci\">grossesse</span> potentiel</strong>. Trois plans de soin : <strong>général</strong>, <strong>étiologique</strong>, <strong>spécifique</strong> (<span class=\"kw-def\">terrain</span> à risque).</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Traitement général</h4>\n      <table >\n        <thead><tr><th>Mesure</th><th>Détails</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-ttt\">Antifibrinolytique</span></td>\n            <td><strong>Acide tranexamique</strong> — diminution des saignements (CI ATCD thrombo-<span class=\"kw-etio\">embolique</span>).</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\">Traitement martial</span></td>\n            <td>Fer <strong>PO</strong> ou <strong>IV</strong> selon la sévérité du déficit / tolérance digestive.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\">Transfusion</span></td>\n            <td>Si <span class=\"kw-alerte\">anémie mal tolérée</span> ou saignement actif sévère.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Traitement étiologique</h4>\n      <table >\n        <thead><tr><th>Cause</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Polype</strong></td>\n            <td><span class=\"kw-ttt\">Résection par hystéroscopie opératoire</span> ± endométrectomie en l’absence de désir de <span class=\"kw-ci\">grossesse</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Adénomyose</strong></td>\n            <td>\n              1. <span class=\"kw-ttt\">DIU au lévonorgestrel</span> (1ʳᵉ intention) ;<br>\n              2. <span class=\"kw-ttt\">Endométrectomie</span> / hystérectomie si échec (cf. obj-7).\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Myome</strong></td>\n            <td>Médical (mise sous aménorrhée) · chirurgical · radiologie interventionnelle (embolisation) — cf. obj-6.</td>\n          </tr>\n          <tr>\n            <td><strong>Malformation artério-veineuse</strong></td>\n            <td><span class=\"kw-imagerie\">Embolisation radiologique</span> — <strong>non délétère sur la fonction ovarienne, préserve la fertilité</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong>Ménométrorragies post-coïtales</strong></td>\n            <td>\n              1. Rechercher une <span class=\"kw-alerte\">pathologie du col</span> (cancer ++, ectropion) ;<br>\n              2. Si <span class=\"kw-clinique\">masse</span> cervicale au spéculum → <strong>colposcopie + <span class=\"kw-bio\">biopsies</span></strong>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Ménométrorragies idiopathiques<br>(fonctionnelles)</strong></td>\n            <td>\n              <strong>Hormonal :</strong> progestatifs PO · COP · DIU au lévonorgestrel ;<br>\n              <strong>Si CI hormonale</strong>, <strong>désir de <span class=\"kw-ci\">grossesse</span></strong> ou saignement important : <span class=\"kw-ttt\">acide tranexamique</span> ;<br>\n              <strong>Si pas de désir de grossesse :</strong> endométrectomie (hystéroscopie / thermodestruction), puis <strong>hystérectomie</strong> en cas d’échec.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Terrains particuliers</h4>\n      <table >\n        <thead><tr><th>Situation</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Sous <span class=\"kw-ttt\">anticoagulants</span></strong></td>\n            <td><span class=\"kw-bio\">Dosage de l’INR en urgence</span> ; <strong>mesures de correction</strong> si surdosage.</td>\n          </tr>\n          <tr>\n            <td><strong>Pas d’<span class=\"kw-ttt\">anticoagulant</span></strong></td>\n            <td>Rechercher une <span class=\"kw-clinique\">pathologie utérine organique</span> (cf. obj-2).</td>\n          </tr>\n          <tr>\n            <td><strong>Maladie de Willebrand type 1</strong></td>\n            <td>Administration de <span class=\"kw-ttt\">desmopressine</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Urgence</span> vitale.</strong> Devant des <span class=\"kw-alerte\">signes de choc</span> : <strong><span class=\"kw-alerte\">hospitalisation</span>, 2 VVP, remplissage, transfusion, β-hCG, <span class=\"kw-bio\">NFS</span>, groupe-Rh (2 dét.), hémostase</strong>. Geste hémostatique d’urgence (<span class=\"kw-ttt\">curetage</span>, embolisation, hystérectomie) selon étiologie.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 35 — Anomalies cycle menstruel - métrorragie · 36 — Contraception · 300 — Tumeurs du col utérin et du corps utérin</em></p>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>Hémorragie grave <span class=\"q\">— <span class=\"kw-alerte\">choc</span> / anémie mal tolérée</span></strong></p><p><span class=\"kw-ttt\">acide tranexamique</span> ± <span class=\"kw-ttt\">transfusion</span> ; geste hémostatique (<span class=\"kw-ttt\">curetage</span> · <span class=\"kw-imagerie\">embolisation</span> · hystérectomie) selon étiologie</p><ul><li><span class=\"kw-alerte\">Hospitalisation</span> · 2 VVP de bon calibre · réchauffement · <span class=\"kw-ttt\">oxygénothérapie</span></li><li><span class=\"kw-bio\">NFS</span> · <span class=\"kw-bio\">hémostase</span> (<span class=\"kw-bio\">TP</span>-TCA) · <span class=\"kw-bio\">groupe-Rh</span> (2 déterminations)</li><li><span class=\"kw-bio\">β-hCG</span> systématique (sauf <span class=\"kw-ci\">grossesse</span> intra-utérine connue)</li></ul>","hospit":"<p><strong>Ambulatoire :</strong> saignement modéré, <span class=\"kw-clinique\">hémodynamique stable</span> → bilan orienté en externe.<br><strong><span class=\"kw-alerte\">Hospitalisation</span> :</strong> <span class=\"kw-alerte\">instabilité hémodynamique</span> / <span class=\"kw-alerte\">anémie mal tolérée</span> / saignement abondant persistant.<br><strong><span class=\"kw-alerte\">Urgence</span> :</strong> suspicion de <span class=\"kw-etio\">grossesse extra-utérine</span> (item 25).</p>","redflags":"<ul><li><span class=\"kw-alerte\">Anémie mal tolérée</span> : <span class=\"kw-clinique\">tachycardie</span> · <span class=\"kw-clinique\">pâleur</span> · <span class=\"kw-clinique\">dyspnée</span> · <span class=\"kw-clinique\">asthénie</span> · <span class=\"kw-clinique\">vertiges</span></li><li><span class=\"kw-alerte\">Choc hémorragique</span> : <span class=\"kw-clinique\">hypotension</span> · <span class=\"kw-clinique\">malaise</span> · <span class=\"kw-clinique\">sueurs</span> · extrémités froides · <span class=\"kw-alerte\">marbrures</span></li><li><span class=\"kw-alerte\">Métrorragie post-ménopausique</span> = <span class=\"kw-etio\">cancer de l’endomètre</span> jusqu’à preuve du contraire</li></ul>","principes":"<p>La PEC dépend de l’<span class=\"kw-etio\">étiologie</span> et du <strong>désir de <span class=\"kw-ci\">grossesse</span></strong>.</p><p><strong>Traitement général <span class=\"q\">— quelle que soit la cause</span></strong></p><ul><li><span class=\"kw-ttt\">Acide tranexamique</span> (antifibrinolytique)</li><li><span class=\"kw-ttt\">Fer</span> PO ou IV · <span class=\"kw-ttt\">transfusion</span> si besoin</li></ul><p><strong>Polype</strong></p><p><span class=\"kw-ttt\">Résection hystéroscopique</span> ± endométrectomie (si pas de désir de <span class=\"kw-ci\">grossesse</span>)</p><p><strong>Adénomyose</strong></p><p>si échec : <span class=\"kw-ttt\">endométrectomie</span> conservatrice → hystérectomie (item 41)</p><ul><li>1ʳᵉ intention : <span class=\"kw-ttt\">DIU au lévonorgestrel</span> (action atrophiante)</li></ul><p><strong>Myome</strong></p><p>médical (aménorrhée) · chirurgical · <span class=\"kw-imagerie\">embolisation</span> (radiologie interventionnelle)</p><p><strong>Coagulopathie / <span class=\"kw-ttt\">anticoagulant</span></strong></p><ul><li>sous AC → <span class=\"kw-bio\">INR</span> en <span class=\"kw-alerte\">urgence</span> ± correction du surdosage</li><li><span class=\"kw-etio\">Willebrand</span> type 1 → <span class=\"kw-ttt\">desmopressine</span> (item 216)</li></ul><p><strong>Malformation artério-veineuse</strong></p><p><span class=\"kw-imagerie\">embolisation radiologique</span> (préserve la fertilité)</p><p><strong>Hémorragie fonctionnelle <span class=\"q\">(idiopathique)</span></strong></p><p>si <span class=\"kw-ci\">CI hormonale</span> / désir de <span class=\"kw-ci\">grossesse</span> → <span class=\"kw-ttt\">acide tranexamique</span> ; <span class=\"kw-ttt\">chirurgie</span> si échec</p><ul><li>hormonal : progestatifs · <span class=\"kw-ttt\">COP</span> · <span class=\"kw-ttt\">DIU-LNG</span></li></ul>","suivi":"<p><strong><span class=\"kw-ttt\">Biopsie</span> d’endomètre</strong> si <span class=\"kw-chiffre\">&gt; 45 ans</span> / ménopause / FR de <span class=\"kw-etio\">cancer de l’endomètre</span>.<br><strong>Hyperplasie atypique</strong> avec désir de <span class=\"kw-ci\">grossesse</span> : contrôle <span class=\"kw-imagerie\">hystéroscopie</span> + <span class=\"kw-bio\">biopsie</span> à <span class=\"kw-chiffre\">6 mois</span> (item 300).<br><strong>Anémie :</strong> correction + <span class=\"kw-bio\">bilan martial</span> (<span class=\"kw-bio\">ferritine</span> + <span class=\"kw-bio\">CRP</span>) — item 213.</p>"},"liensGlobaux":[{"href":"https://www.chu-lyon.fr/sites/default/files/score-higham.pdf","label":"chu-lyon.fr"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Hémorragie génitale chez la femme — 1er temps : évaluer la tolérance hémodynamique","detail":"<h4>CAT — hémorragie génitale chez la femme — Orientation : <span class=\"kw-alerte\">urgence</span> → β-hCG → origine → <span class=\"kw-def\">terrain</span></h4>","branches":[{"to":"t-urgence","label":"Signes de choc / anémie mal tolérée","color":"red"},{"to":"q-hcg","label":"Hémodynamique stable","color":"green"}]},{"id":"t-urgence","kind":"terminal","label":"Urgence hémorragique","color":"red","detail":"<h4>Conduite immédiate</h4><ul><li><span class=\"kw-ttt\">Hospitalisation</span> · 2 VVP de bon calibre · remplissage</li><li><span class=\"kw-ttt\">Transfusion</span> + <span class=\"kw-ttt\">acide tranexamique</span></li><li>Geste hémostatique (<span class=\"kw-ttt\">curetage</span> · <span class=\"kw-imagerie\">embolisation</span> · hystérectomie) selon étiologie</li></ul><h4>Bilan en <span class=\"kw-alerte\">urgence</span></h4><ul><li><span class=\"kw-bio\">NFS</span> · <span class=\"kw-bio\">hémostase</span> · <span class=\"kw-bio\">groupe-Rh</span> (2 dét.) · <span class=\"kw-bio\">β-hCG</span></li></ul><h4>Puis</h4><ul><li>Démarche étiologique une fois la patiente stabilisée</li></ul>"},{"id":"q-hcg","kind":"decision","label":"β-hCG ? — Systématique chez toute femme en âge de procréer","branches":[{"to":"t-grossesse","label":"Positive","color":"red"},{"to":"q-origine","label":"Négative","color":"green"}]},{"id":"t-grossesse","kind":"terminal","label":"Cause obstétricale","color":"red","detail":"<h4>Démarche</h4><ul><li><span class=\"kw-imagerie\">Échographie pelvienne</span> en <span class=\"kw-alerte\">urgence</span></li></ul><h4>À éliminer</h4><ul><li><span class=\"kw-alerte\">Grossesse extra-utérine</span> (item 25)</li><li>Fausse couche spontanée · môle hydatiforme</li><li><span class=\"kw-ci\">Grossesse</span> intra-utérine évolutive (item 23)</li></ul>"},{"id":"q-origine","kind":"decision","label":"Origine au spéculum ? — Haute (endo-utérine) vs basse (cervico-vaginale)","branches":[{"to":"t-basse","label":"Basse — cervico-vaginale","color":"amber"},{"to":"q-echo","label":"Haute — endo-utérine","color":"blue"}]},{"id":"t-basse","kind":"terminal","label":"Cause cervico-vaginale","color":"amber","detail":"<h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Ectropion</span> · <span class=\"kw-etio\">cervicite</span> · traumatisme</li><li><span class=\"kw-alerte\">Cancer du col</span> ++ (saignement post-coïtal)</li></ul><h4>Exploration</h4><ul><li>Si <span class=\"kw-clinique\">lésion</span> / <span class=\"kw-clinique\">masse</span> cervicale → <span class=\"kw-ttt\">colposcopie</span> + <span class=\"kw-bio\">biopsies dirigées</span> (item 300)</li></ul>"},{"id":"q-echo","kind":"decision","label":"Échographie pelvienne (1ʳᵉ intention) — Voie abdominale + endovaginale","branches":[{"to":"t-organique","label":"Anomalie organique","color":"amber"},{"to":"q-terrain","label":"Échographie normale","color":"blue"}]},{"id":"t-organique","kind":"terminal","label":"Cause organique (PALM)","color":"amber","detail":"<h4>Lésions</h4><ul><li><span class=\"kw-etio\">Polype</span> · <span class=\"kw-etio\">myome sous-muqueux</span></li><li><span class=\"kw-etio\">Adénomyose</span> (item 41)</li><li><span class=\"kw-etio\">Hyperplasie endométriale</span> / <span class=\"kw-alerte\">cancer de l’endomètre</span></li></ul><h4>2ⁿᵈ intention</h4><ul><li><span class=\"kw-imagerie\">IRM pelvienne</span> ou <span class=\"kw-imagerie\">hystéroscopie</span> ± <span class=\"kw-bio\">biopsie</span></li></ul><h4>Traitement</h4><ul><li>Selon la <span class=\"kw-clinique\">lésion</span> (item 300)</li></ul>"},{"id":"q-terrain","kind":"decision","label":"Terrain ?","branches":[{"to":"t-menopause","label":"Ménopausée","color":"red"},{"to":"t-fonctionnelle","label":"Âge de procréer / adolescente","color":"green"}]},{"id":"t-menopause","kind":"terminal","label":"Cancer jusqu’à preuve du contraire","color":"red","detail":"<h4>Impératif</h4><ul><li><span class=\"kw-bio\">Biopsie d’endomètre</span> systématique (item 300)</li></ul><h4>À éliminer</h4><ul><li><span class=\"kw-alerte\">Cancer de l’endomètre</span></li><li><span class=\"kw-alerte\">Cancer du col</span> · ovaire sécrétant des stéroïdes (item 306)</li></ul><h4>Diagnostic d’exclusion</h4><ul><li><span class=\"kw-etio\">Atrophie endométriale</span></li></ul>"},{"id":"t-fonctionnelle","kind":"terminal","label":"Hémorragie fonctionnelle","color":"green","detail":"<h4>Diagnostic d’élimination</h4><ul><li>Déséquilibre œstro-progestatif, sans substratum organique</li></ul><h4>À rechercher</h4><ul><li>Bilan d’hémostase — <span class=\"kw-etio\">Willebrand</span> chez l’adolescente (item 216)</li><li>Cause <span class=\"kw-etio\">iatrogène</span> : <span class=\"kw-etio\">contraception</span> (item 36) · <span class=\"kw-etio\">anticoagulant</span></li><li>Insuffisance lutéale · métrorragie ovulatoire du 14ᵉ jour</li></ul><h4>Traitement</h4><ul><li>Hormonal (progestatifs · <span class=\"kw-ttt\">COP</span> · <span class=\"kw-ttt\">DIU-LNG</span>) ± <span class=\"kw-ttt\">acide tranexamique</span></li></ul>"}]},"cards":[{"i":"405ff0eea89e","n":43,"o":"43-1","u":"Diagnostic","t":"Déterminer, par l’examen clinique, l’origine du saignement et le quantifier","q":"Quels sont les signes cliniques de gravité permettant d'identifier une urgence face à une hémorragie génitale chez la femme et quelle est la conduite à tenir immédiate ?","a":"<p>Les signes de gravité à repérer d'emblée sont liés à :</p><ul><li>Une <strong>anémie mal tolérée</strong> : <strong>tachycardie</strong>, <strong>pâleur</strong>, <strong>dyspnée</strong>, <strong>asthénie</strong>, <strong>vertiges</strong>.</li><li>Un <strong>choc hypovolémique</strong> : <strong>hypotension</strong>, <strong>malaise</strong>, <strong>sueurs</strong>, <strong>extrémités froides</strong>, <strong>marbrures</strong>.</li></ul><p>La conduite à tenir immédiate comprend :</p><ul><li><strong>Hospitalisation</strong>.</li><li>Pose de <strong>2 voies veineuses périphériques (VVP) de bon calibre</strong>.</li><li><strong>Réchauffement</strong> et <strong>oxygénothérapie</strong>.</li><li>Prélèvements sanguins : <strong>NFS</strong>, bilan d'<strong>hémostase</strong>, <strong>groupe sanguin et Rhésus</strong> (avec 2 déterminations), <strong>β-hCG</strong> (sauf grossesse intra-utérine connue).</li></ul>"},{"i":"4981a91b6a87","n":43,"o":"43-1","u":"Diagnostic","t":"Déterminer, par l’examen clinique, l’origine du saignement et le quantifier","q":"Comment définit-on cliniquement une hémorragie génitale chez la femme et quels sont les objectifs primordiaux de la démarche clinique immédiate ?","a":"<p>Une hémorragie génitale est caractérisée par des <strong>pertes sanguines d'origine génitale extériorisées par l'orifice vulvaire</strong>, qui diffèrent des règles normales.</p><p>Les objectifs cliniques primordiaux sont :</p><ul><li><strong>Localiser l'origine du saignement</strong> (haute ou basse).</li><li><strong>Quantifier le saignement</strong>.</li><li><strong>Rechercher des signes de gravité</strong>.</li></ul>"},{"i":"61b767f2286e","n":43,"o":"43-1","u":"Diagnostic","t":"Déterminer, par l’examen clinique, l’origine du saignement et le quantifier","q":"Comment l'examen clinique permet-il de localiser l'origine d'une hémorragie génitale et de la quantifier chez la femme ?","a":"<p>L'examen clinique permet de localiser et quantifier l'hémorragie génitale de la manière suivante :</p><ul><li><strong>Interrogatoire</strong> : Il permet une quantification initiale par le nombre de garnitures utilisées (serviettes, tampons), la présence de caillots et de vêtements tachés. Le <strong>Score de Higham</strong> est utilisé pour les ménorragies (<strong>> 100 mL</strong> = ménorragies, <strong>> 150-200 mL</strong> = saignement très abondant nécessitant une prise en charge spécifique).</li><li><strong>Examen sous spéculum</strong> : Permet la visualisation directe de l'origine du saignement (endo-utérin, cervical, vaginal) et la recherche de lésions spécifiques (polype accouché par le col, ectropion).</li><li><strong>Toucher vaginal</strong> : Évalue le volume utérin et recherche une tuméfaction latéro-utérine.</li></ul>"},{"i":"bfc27535c13b","n":43,"o":"43-1","u":"Diagnostic","t":"Déterminer, par l’examen clinique, l’origine du saignement et le quantifier","q":"Quelles sont les définitions des différents types d'hémorragies génitales anormales chez la femme ?","a":"<p>Les différents types d'hémorragies génitales anormales sont :</p><ul><li><strong>Ménorragies</strong> : Menstruations trop abondantes en volume (<strong>> 80 mL</strong>) ou en durée (<strong>> 6 jours</strong>). Elles se subdivisent en :<ul><li><strong>Hyperménorrhées</strong> : Durée normale, mais abondance supérieure à 80 mL.</li><li><strong>Macroménorrhées</strong> : Durée supérieure à 6 jours, mais abondance normale.</li><li><strong>Polyménorrhées</strong> : Anomalie de durée <strong>ET</strong> d'abondance.</li></ul></li><li><strong>Métrorragies</strong> : Saignements d'origine utérine survenant <strong>entre les périodes de menstruation</strong>.</li><li><strong>Ménométrorragies</strong> : Association de ménorragies et de métrorragies.</li></ul>"},{"i":"0ef787dd9d69","n":43,"o":"43-2","u":"Étiologies","t":"Connaître les principales causes d’hémorragie génitale","q":"Quelles sont les principales causes d'hémorragie génitale à évoquer chez une adolescente ?","a":"<p>Chez une adolescente, les principales causes d'hémorragie génitale à évoquer sont :</p><ul><li>Les <srong>anomalies de l’hémostase</srong> (notamment la maladie de <srong>Willebrand</srong>+++)</li><li>Les <srong>causes fonctionnelles</srong> : insuffisance lutéale, hyperœstrogénie relative par anovulation des premiers cycles.</li></ul>"},{"i":"3b86bc702355","n":43,"o":"43-2","u":"Étiologies","t":"Connaître les principales causes d’hémorragie génitale","q":"Selon la classification FIGO PALM-COEIN, quelles sont les causes structurelles (PALM) d'hémorragie génitale ?","a":"<p>Les causes structurelles (PALM) d'hémorragie génitale comprennent :</p><ul><li><strong>P</strong> : Polype</li><li><strong>A</strong> : Adénomyose</li><li><strong>L</strong> : Léiomyome (sous-muqueux et autre)</li><li><strong>M</strong> : Malignité et hyperplasie</li></ul>"},{"i":"8377c1e8a84b","n":43,"o":"43-2","u":"Étiologies","t":"Connaître les principales causes d’hémorragie génitale","q":"Selon la classification FIGO PALM-COEIN, quelles sont les causes non structurelles (COEIN) d'hémorragie génitale ?","a":"<p>Les causes non structurelles (COEIN) d'hémorragie génitale comprennent :</p><ul><li><strong>C</strong> : Coagulopathie</li><li><strong>O</strong> : Ovulatoire (dysfonction)</li><li><strong>E</strong> : Endométriale</li><li><strong>I</strong> : Iatrogénie</li><li><strong>N</strong> : Non autrement précisée</li></ul>"},{"i":"9cdcf44ec7f3","n":43,"o":"43-2","u":"Étiologies","t":"Connaître les principales causes d’hémorragie génitale","q":"Quelles sont les principales causes d'hémorragie génitale au premier trimestre de la grossesse ?","a":"<p>Les principales causes d'hémorragie génitale au premier trimestre de la grossesse sont :</p><ul><li>Grossesse intra-utérine évolutive</li><li>Grossesse extra-utérine (GEU)</li><li>Grossesse de localisation indéterminée</li><li>Fausse couche spontanée (FCS)</li><li>Grossesse arrêtée</li><li>Môle hydatiforme</li></ul>"},{"i":"c19f1669a38c","n":43,"o":"43-2","u":"Étiologies","t":"Connaître les principales causes d’hémorragie génitale","q":"Quelles sont les principales causes d'hémorragie génitale au troisième trimestre de la grossesse ?","a":"<p>Les principales causes d'hémorragie génitale au troisième trimestre de la grossesse incluent :</p><ul><li>Hématome rétroplacentaire (HRP)</li><li>Hématome décidual marginal</li><li>Placenta prævia</li><li>Hémorragie de Benkiser</li><li>Rupture utérine</li><li>Cause cervicale</li><li>Hémorragies de la délivrance (post-partum immédiat)</li></ul>"},{"i":"dda857518de1","n":43,"o":"43-2","u":"Étiologies","t":"Connaître les principales causes d’hémorragie génitale","q":"Devant une métrorragie chez une femme ménopausée, quelle étiologie doit être suspectée en priorité ?","a":"<p>Chez une femme ménopausée, <srong>toute métrorragie doit faire suspecter un cancer</srong> (endomètre, col, ovaire sécrétant) jusqu'à preuve du contraire. L'atrophie endométriale est un diagnostic d'exclusion.</p>"},{"i":"fd0f3a36b71b","n":43,"o":"43-2","u":"Étiologies","t":"Connaître les principales causes d’hémorragie génitale","q":"Quelle est la première chose à éliminer devant une hémorragie génitale chez une femme en âge de procréer ?","a":"<p>Devant toute hémorragie génitale chez une femme en âge de procréer, il faut <srong>impérativement éliminer une grossesse</srong>, notamment par le dosage de la <srong>β-hCG plasmatique ou urinaire</srong>.</p>"},{"i":"17ba29521575","n":43,"o":"43-3","u":"Étiologies","t":"Différencier les causes organiques et les causes fonctionnelles","q":"Comment différencier les hémorragies génitales organiques des hémorragies génitales fonctionnelles sur le plan diagnostique ?","a":"<p>La distinction entre causes organiques et fonctionnelles est fondamentale pour la stratégie diagnostique. Le diagnostic de cause <strong>fonctionnelle</strong> est un <strong>diagnostic d'élimination</strong>, qui ne peut être posé qu'après un <strong>bilan organique normal</strong>, incluant une <strong>imagerie pelvienne</strong> et, selon le terrain, une <strong>biopsie d'endomètre</strong> normale.</p>"},{"i":"2e3cd99fbf10","n":43,"o":"43-3","u":"Étiologies","t":"Différencier les causes organiques et les causes fonctionnelles","q":"Dans quel contexte clinique les hémorragies génitales fonctionnelles sont-elles les plus fréquentes, et quels sont leurs tableaux cliniques types ?","a":"<p>Ces hémorragies sont fréquentes en période de <strong>péri-puberté</strong> et de <strong>péri-ménopause</strong>. Les trois tableaux types sont :</p><ul><li>Les <strong>métrorragies prémenstruelles</strong> par insuffisance lutéale.</li><li>Les <strong>métrorragies intermenstruelles du 14ᵉ jour</strong> (liées à l'ovulation).</li><li>Les <strong>métrorragies post-menstruelles</strong> par insuffisance œstrogénique en début de cycle.</li></ul>"},{"i":"438f27a14f55","n":43,"o":"43-3","u":"Étiologies","t":"Différencier les causes organiques et les causes fonctionnelles","q":"Quelles sont les causes organiques systémiques, iatrogènes ou liées à la coagulation, responsables d'hémorragies génitales ?","a":"<ul><li><strong>Coagulopathie</strong> : notamment la <strong>maladie de Willebrand</strong>.</li><li><strong>Iatrogènes</strong> : contraception (carence œstrogénique), <strong>anticoagulants</strong>, DIU (dispositif intra-utérin).</li><li><strong>Systémiques</strong> : <strong>hypothyroïdie</strong>, lupus, insuffisance rénale chronique, insuffisance hépatique.</li></ul>"},{"i":"f2f8c15003f4","n":43,"o":"43-3","u":"Étiologies","t":"Différencier les causes organiques et les causes fonctionnelles","q":"Quelles sont les caractéristiques des hémorragies génitales fonctionnelles et leur mécanisme principal ?","a":"<p>Les hémorragies génitales fonctionnelles sont un <strong>diagnostic d'élimination</strong>. Elles se caractérisent par un <strong>déséquilibre hormonal œstrogène / progestérone</strong> induisant une altération de l'endomètre. Par définition, il n'existe <strong>pas de substratum histopathologique utérin</strong>.</p>"},{"i":"f33490b7be11","n":43,"o":"43-3","u":"Étiologies","t":"Différencier les causes organiques et les causes fonctionnelles","q":"Quelles sont les principales causes organiques d'hémorragie génitale chez la femme, classées par site anatomique ?","a":"<ul><li><strong>Vulve</strong> : Traumatisme, tumeur vulvaire.</li><li><strong>Vagin</strong> : Traumatisme, corps étranger, vaginite, tumeur vaginale.</li><li><strong>Col</strong> : Traumatisme, ectropion, <strong>cancer du col</strong>, cervicite.</li><li><strong>Endomètre</strong> : Endométrite, <strong>polype endométrial</strong>, <strong>hyperplasies endométriales</strong> (simples ou atypiques), <strong>cancer de l’endomètre</strong> (fréquent en péri-ménopause).</li><li><strong>Myomètre</strong> : <strong>Myome sous-muqueux</strong>, adénomyose, sarcome utérin.</li><li><strong>Annexe / ovaire</strong> : Salpingite, kyste / tumeur ovarienne sécrétante de stéroïdes.</li></ul>"},{"i":"775872e4dbf1","n":43,"o":"43-4","u":"Examens complémentaires","t":"Savoir prescrire les premiers examens biologiques à réaliser","q":"Quand faut-il demander un bilan martial, un dosage du facteur de Willebrand et des prélèvements bactériologiques cervico-vaginaux devant une hémorragie génitale ?","a":"<ul><li><strong>Bilan martial</strong> (ferritinémie + CRP) : pour évaluer les conséquences à long terme et dépister une carence martiale. La CRP est utile car un syndrome inflammatoire peut masquer une hypoferritinémie.</li><li><strong>Dosage du facteur de Willebrand</strong> : a une indication large chez l'adolescente.</li><li><strong>Prélèvements bactériologiques cervico-vaginaux</strong> : si un risque infectieux est suspecté, et si positifs, ils seront suivis de sérologies des hépatites B et C, du VIH et de la syphilis.</li></ul>"},{"i":"94a08771989e","n":43,"o":"43-4","u":"Examens complémentaires","t":"Savoir prescrire les premiers examens biologiques à réaliser","q":"Quel est l'objectif principal du bilan biologique de première intention face à une hémorragie génitale chez la femme ?","a":"<p>L'objectif principal est de <strong>chiffrer la spoliation</strong>, d'<strong>éliminer une grossesse</strong> et de <strong>dépister une coagulopathie</strong>.</p>"},{"i":"a7996bb887eb","n":43,"o":"43-4","u":"Examens complémentaires","t":"Savoir prescrire les premiers examens biologiques à réaliser","q":"Quels sont les examens biologiques systématiques à réaliser en première intention en cas d'hémorragie génitale sévère, et leur utilité respective ?","a":"<ul><li><strong>NFS</strong> : pour la quantification du retentissement (hémoglobine) et des plaquettes.</li><li><strong>Bilan d'hémostase</strong> : TP, TCA.</li><li><strong>Groupe sanguin / Rh</strong> (2 déterminations) : en prévision d'une potentielle transfusion.</li><li><strong>β-hCG plasmatique ou urinaire</strong> : systématique pour éliminer une grossesse.</li></ul>"},{"i":"61f7e7487b15","n":43,"o":"43-5","u":"Examens complémentaires","t":"Connaître l’indication de l’imagerie devant une hémorragie génitale chez la femme","q":"Dans quels cas une IRM pelvienne est-elle indiquée en deuxième intention pour une hémorragie génitale ?","a":"<p>Une IRM pelvienne (avec injection) est indiquée en deuxième intention pour :</p><ul><li>La <strong>cartographie précise des myomes</strong> (avant chirurgie ou embolisation)</li><li>Le bilan d'<strong>adénomyose</strong></li><li>La <strong>suspicion de cancer utérin</strong></li><li>Les <strong>malformations utérines complexes</strong></li></ul>"},{"i":"934415c1de99","n":43,"o":"43-5","u":"Examens complémentaires","t":"Connaître l’indication de l’imagerie devant une hémorragie génitale chez la femme","q":"Quelle est la prise en charge d'une hémorragie génitale basse ou d'un saignement post-coïtal objectivé au spéculum ?","a":"<p>La prise en charge comprend :</p><ul><li>Une <strong>colposcopie</strong>, suivie de <strong>biopsies cervicales dirigées</strong> pour le diagnostic anatomopathologique.</li><li>Le <strong>FCU</strong> (frottis cervico-utérin) ou le <strong>test HPV</strong> sont possibles mais leurs résultats peuvent être faussés par le sang, et ils ne sont <strong>pas indiqués si une lésion cervicale est visible</strong>.</li></ul>"},{"i":"b3823a2a87e2","n":43,"o":"43-5","u":"Examens complémentaires","t":"Connaître l’indication de l’imagerie devant une hémorragie génitale chez la femme","q":"Quand une hystérosonographie ou une hystéroscopie diagnostique sont-elles indiquées en deuxième intention pour une hémorragie génitale ?","a":"<p>Ces examens sont indiqués en deuxième intention pour une meilleure analyse de la cavité utérine si :</p><ul><li>Échec d'un <strong>traitement médicamenteux</strong> alors que l'échographie était normale</li><li>Présence d'une <strong>lésion endométriale à l'échographie</strong> (polype, hyperplasie atypique, myome sous-muqueux)</li></ul>"},{"i":"f0619d989b3e","n":43,"o":"43-5","u":"Examens complémentaires","t":"Connaître l’indication de l’imagerie devant une hémorragie génitale chez la femme","q":"Quelle est l'imagerie de première intention en cas d'hémorragie génitale chez la femme, après élimination d'une grossesse pathologique ?","a":"<p>L'imagerie de première intention est l'<strong>échographie pelvienne</strong> (par voies <strong>sus-pubienne et endovaginale</strong>).</p>"},{"i":"fe31e06f372c","n":43,"o":"43-5","u":"Examens complémentaires","t":"Connaître l’indication de l’imagerie devant une hémorragie génitale chez la femme","q":"Quels sont les éléments recherchés lors d'une échographie pelvienne de première intention pour une hémorragie génitale ?","a":"<p>L'échographie pelvienne recherche la présence d'un <ul><li><strong>polype</strong></li><li><strong>myome</strong></li><li><strong>adénomyose</strong></li><li><strong>masse annexielle</strong></li></ul> et évalue l'<strong>épaisseur endométriale</strong>.</p>"}]};